-- Re-runnable except the ALTER TABLE ... ADD COLUMN (see
-- scripts/migration-forward-fix.mjs for a suspected partial apply).
-- WIP, disabled unless the existing undo serialization activation is armed.
-- Freeze a cancelled expense's historical projection manifest from the
-- source transition onward, through every REVOKE/FINAL stage and thereafter.
-- An unresolved late confirmed write must be reconciled, never admitted here.
CREATE TABLE IF NOT EXISTS continuous_cancel_financial_activation(singleton INTEGER PRIMARY KEY CHECK(singleton=1),activated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS continuous_cancel_financial_activation_insert BEFORE INSERT ON continuous_cancel_financial_activation WHEN NOT EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'financial cancellation requires serialization'); END;
CREATE TRIGGER IF NOT EXISTS continuous_cancel_financial_activation_no_update BEFORE UPDATE ON continuous_cancel_financial_activation BEGIN SELECT RAISE(ABORT,'financial cancellation activation retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_cancel_financial_activation_no_delete BEFORE DELETE ON continuous_cancel_financial_activation BEGIN SELECT RAISE(ABORT,'financial cancellation activation retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_cancel_financial_activation_no_replace BEFORE INSERT ON continuous_cancel_financial_activation WHEN EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=NEW.singleton OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'financial cancellation activation collision'); END;
CREATE TABLE IF NOT EXISTS continuous_financial_journal_revision(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(revision>=0));
-- A conditional insert, not OR IGNORE: on a re-run the no_replace trigger below
-- already exists and would ABORT any attempted insert.
INSERT INTO continuous_financial_journal_revision(singleton,revision) SELECT 1,0 WHERE NOT EXISTS(SELECT 1 FROM continuous_financial_journal_revision WHERE singleton=1);
CREATE TRIGGER IF NOT EXISTS continuous_financial_journal_revision_no_delete BEFORE DELETE ON continuous_financial_journal_revision BEGIN SELECT RAISE(ABORT,'financial journal revision retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_journal_revision_no_replace BEFORE INSERT ON continuous_financial_journal_revision WHEN EXISTS(SELECT 1 FROM continuous_financial_journal_revision WHERE singleton=NEW.singleton OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'financial journal revision collision'); END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_journal_revision_monotonic BEFORE UPDATE ON continuous_financial_journal_revision WHEN NEW.singleton IS NOT OLD.singleton OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'financial journal revision invalid'); END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_projection_insert_revision AFTER INSERT ON stable_projection_writes WHEN NEW.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_projection_update_revision AFTER UPDATE ON stable_projection_writes WHEN OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_projection_delete_revision AFTER DELETE ON stable_projection_writes WHEN OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_preimage_insert_revision AFTER INSERT ON stable_expense_projection_preimages WHEN NEW.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_preimage_update_revision AFTER UPDATE ON stable_expense_projection_preimages WHEN OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
CREATE TRIGGER IF NOT EXISTS continuous_financial_preimage_delete_revision AFTER DELETE ON stable_expense_projection_preimages WHEN OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) BEGIN UPDATE continuous_financial_journal_revision SET revision=revision+1 WHERE singleton=1; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'financial journal revision missing') END; END;
ALTER TABLE continuous_publication_intents ADD COLUMN financial_journal_revision INTEGER;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_journal_revision_insert BEFORE INSERT ON continuous_publication_intents WHEN NEW.kind='REVOKE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) AND NOT EXISTS(SELECT 1 FROM continuous_financial_journal_revision r WHERE r.singleton=1 AND r.revision=NEW.financial_journal_revision) BEGIN SELECT RAISE(ABORT,'revocation journal snapshot stale'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_journal_revision_immutable BEFORE UPDATE OF financial_journal_revision ON continuous_publication_intents WHEN OLD.financial_journal_revision IS NOT NEW.financial_journal_revision BEGIN SELECT RAISE(ABORT,'revocation journal snapshot immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_projection_insert_fence BEFORE INSERT ON stable_projection_writes
WHEN NEW.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM expense_events e JOIN continuous_publication_markers m ON m.entity_id=e.expense_id AND m.spreadsheet_id=NEW.spreadsheet_id WHERE e.status='CANCELLED' AND (NEW.entity_id=e.expense_id OR substr(NEW.entity_id,1,length(e.expense_id)+1)=e.expense_id||'|'))
BEGIN SELECT RAISE(ABORT,'revocation projection manifest is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_projection_update_fence BEFORE UPDATE ON stable_projection_writes
WHEN OLD.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM expense_events e JOIN continuous_publication_markers m ON m.entity_id=e.expense_id AND m.spreadsheet_id=OLD.spreadsheet_id WHERE e.status='CANCELLED' AND (OLD.entity_id=e.expense_id OR substr(OLD.entity_id,1,length(e.expense_id)+1)=e.expense_id||'|'))
BEGIN SELECT RAISE(ABORT,'revocation projection manifest is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_preimage_insert_fence BEFORE INSERT ON stable_expense_projection_preimages
WHEN NEW.entity_type='EXPENSE' AND EXISTS(SELECT 1 FROM continuous_cancel_financial_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM expense_events e JOIN continuous_publication_markers m ON m.entity_id=e.expense_id AND m.spreadsheet_id=NEW.spreadsheet_id WHERE e.status='CANCELLED' AND (NEW.entity_id=e.expense_id OR substr(NEW.entity_id,1,length(e.expense_id)+1)=e.expense_id||'|'))
BEGIN SELECT RAISE(ABORT,'revocation projection manifest is resolving'); END;
